/** Whether this /output path is a model's results file (`<folder>/model.json`). */
export function isModelResultsFilename(filename: string): boolean {
  const normalized = filename.replace(/^\/?output\//, '');
  return normalized.endsWith(`/${MODEL_RESULTS_FILENAME}`);
}

/** Why the text isn't a readable model results file, or null when it is. */
export function modelResultsProblem(text: string): string | null {
  let candidate: unknown;
  try {
    candidate = JSON.parse(text);
  } catch (error) {
    return `it isn't valid JSON (${error instanceof Error ? error.message : String(error)})`;
  }
  const parsed = modelResultsSchema.safeParse(candidate);
  if (parsed.success) return null;
  return parsed.error.issues
    .slice(0, 5)
    .map((issue) => `${issue.path.length > 0 ? issue.path.join('.') : '(top level)'}: ${issue.message}`)
    .join('; ');
}

/** The results, or null when the text isn't a readable results file. */
export function parseModelResults(text: string): ModelResultsV1 | null {
  try {
    const parsed = modelResultsSchema.safeParse(JSON.parse(text));
    return parsed.success ? parsed.data : null;
  } catch {
    return null;
  }
}
